/**
 * Seed 350 destinations — 60 Indian + 290 international.
 * Run: npx tsx src/db/seedDestinations350.ts
 */
import 'dotenv/config';
import { db } from '../config/database';
import { destinations } from './schema/hotels';

const BATCH_SIZE = 50;

type Dest = typeof destinations.$inferInsert;

/* ──────────────────────────────────────────────────────────────────────────────
   HELPER – shortens each destination entry
   ────────────────────────────────────────────────────────────────────────────── */
function d(p: {
  slug: string; name: string; country: string; cc: string; continent: string;
  lat: string; lng: string; airports: string[]; hero: string;
  tagline: string; desc: string; moods: string[];
  budget: [number, number, number]; // [budget, mid, luxury] INR/day
  visa: 'visa_free' | 'visa_on_arrival' | 'e_visa' | 'visa_required';
  visaFee?: number; visaDays?: number;
  tags: string[]; bestMonths: number[]; avoidMonths?: number[]; peakMonths?: number[];
  safety: number; weather: number; infra: number; value: number;
  flightHrs: [number, number]; directFrom?: string[];
  nearestAirport?: string; domestic?: boolean; state?: string;
  trending?: number; trendingPct?: number; flag: string;
  rank: number; popular?: number; isTrending?: number; hiddenGem?: number;
  currency: string; tz: string; utc: number;
  activities: string[]; cuisine: string[]; tips: string[];
  duration?: [number, number]; crowd?: string; weatherSummary?: string;
  safetyRating?: number; langBarrier?: string;
}): Dest {
  return {
    slug: p.slug,
    name: p.name,
    country: p.country,
    countryCode: p.cc,
    continent: p.continent,
    lat: p.lat,
    lng: p.lng,
    airportCodes: p.airports,
    heroImageUrl: p.hero,
    tagline: p.tagline,
    description: p.desc,
    moodsJson: p.moods,
    scoreJson: {
      overall: Math.round((p.safety + p.weather + p.infra + p.value) / 4),
      affordability: p.value,
      safety: p.safety,
      weatherScore: p.weather,
      touristInfrastructure: p.infra,
      uniqueness: 75,
      visaEase: p.visa === 'visa_free' ? 99 : p.visa === 'visa_on_arrival' ? 85 : p.visa === 'e_visa' ? 70 : 40,
      travelTime: Math.round(100 - p.flightHrs[1] * 5),
      communityRating: Math.round((p.safety + p.value) / 2),
      badge: p.hiddenGem ? 'hidden_gem' : (p.isTrending ? 'trending' : 'popular'),
    },
    budgetJson: {
      budget:  { amount: p.budget[0], currency: 'INR', formatted: `₹${p.budget[0].toLocaleString('en-IN')}` },
      comfort: { amount: p.budget[1], currency: 'INR', formatted: `₹${p.budget[1].toLocaleString('en-IN')}` },
      luxury:  { amount: p.budget[2], currency: 'INR', formatted: `₹${p.budget[2].toLocaleString('en-IN')}` },
      flightFrom: { amount: p.domestic ? p.budget[0] * 2 : p.budget[1] * 3, currency: 'INR', formatted: `₹${(p.domestic ? p.budget[0] * 2 : p.budget[1] * 3).toLocaleString('en-IN')}` },
      averageHotelPerNight: { amount: p.budget[1], currency: 'INR', formatted: `₹${p.budget[1].toLocaleString('en-IN')}` },
      averageMealCost: { amount: Math.round(p.budget[0] * 0.25), currency: 'INR', formatted: `₹${Math.round(p.budget[0] * 0.25).toLocaleString('en-IN')}` },
    },
    visaJson: {
      type: p.visa,
      durationDays: p.domestic ? 365 : (p.visaDays ?? 30),
      feeUsd: p.visaFee ?? 0,
      processingDays: p.visa === 'visa_required' ? 10 : 0,
    },
    highlightsJson: [],
    bestTimeJson: [{
      months: p.bestMonths,
      reason: 'Best weather and travel conditions',
      weather: 'Pleasant',
      crowdLevel: p.crowd ?? 'medium',
      priceLevel: 'moderate',
    }],
    popularActivities: p.activities,
    cuisineHighlights: p.cuisine,
    localTips: p.tips,
    safetyRating: p.safetyRating ?? Math.round(p.safety / 10),
    languageBarrier: p.langBarrier ?? 'low',
    currency: p.currency,
    timezoneName: p.tz,
    utcOffset: p.utc,
    isPopular: p.popular ?? (p.rank <= 50 ? 1 : 0),
    isTrending: p.isTrending ?? 0,
    isHiddenGem: p.hiddenGem ?? 0,
    rank: p.rank,
    safetyScore: p.safety,
    weatherScore: p.weather,
    infrastructureScore: p.infra,
    valueScore: p.value,
    budgetPerDay: p.budget[0],
    budgetMidPerDay: p.budget[1],
    budgetLuxuryPerDay: p.budget[2],
    visaStatus: p.visa,
    visaFeeInr: p.visaFee ? p.visaFee * 83 : 0,
    visaProcessingDays: p.visa === 'visa_required' ? 10 : 0,
    tags: p.tags,
    bestMonths: p.bestMonths,
    avoidMonths: p.avoidMonths ?? [],
    peakMonths: p.peakMonths ?? p.bestMonths.slice(0, 3),
    weatherSummary: p.weatherSummary ?? 'Pleasant weather during recommended months',
    flightHoursMin: p.flightHrs[0],
    flightHoursMax: p.flightHrs[1],
    directFlightCities: p.directFrom ?? [],
    nearestAirportCode: p.nearestAirport ?? p.airports[0] ?? null,
    isDomestic: p.domestic ?? false,
    stateProvince: p.state ?? null,
    trendingScore: p.trending ?? 50,
    trendingChangePct: p.trendingPct ?? 0,
    flagEmoji: p.flag,
    galleryImages: [],
    nearbyDestinations: [],
    crowdLevel: p.crowd ?? 'Medium',
    idealDurationMin: p.duration?.[0] ?? 3,
    idealDurationMax: p.duration?.[1] ?? 7,
  };
}

